\documentclass[11pt]{article}
\usepackage[review,hyperref]{acl}
\usepackage{times}
\usepackage{latexsym}
\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{graphicx}
\usepackage{booktabs}
\usepackage{multirow}
\usepackage{xcolor}
\usepackage{subcaption}
\usepackage{algorithm}
\usepackage{algpseudocode}
\usepackage{float}

\title{Not All Models Are Inflated: Profiling Contamination Dose-Response Across Model Families}

\author{Anonymous}

\begin{document}
\maketitle

\begin{abstract}
\input{abstract}
\end{abstract}

\input{introduction}
\input{related_work}
\input{method}
\input{experimental_setup}
\input{results}
\input{conclusion}

\input{limitations}
\input{ethics}

\bibliography{references}

\input{appendix}

\end{document}

